package glitch

import data.glitch_lib

# Check for hard-coded credentials by matching common password-related attribute names
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for common credential-related attribute names
    is_credential_attribute(attr.name)

    # Check if value is a hard-coded string (not a variable reference)
    attr.value.ir_type == "String"

    # Ensure it's not empty and looks like an actual credential value
    count(attr.value.value) > 0
    not looks_like_variable_reference(attr.value.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Avoid hard-coding passwords, API keys, or cryptographic secrets in configuration files. Use secure vaults or environment variables instead. (CWE-798)"
    }
}

# Check for hard-coded credentials in variable definitions
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    v := vars[_]

    # Check for common credential-related variable names
    is_credential_variable(v.name)

    # Check if value is a hard-coded string
    v.value.ir_type == "String"

    # Ensure it's not empty and looks like an actual credential value
    count(v.value.value) > 0
    not looks_like_variable_reference(v.value.value)

    result := {
        "type": "sec_hard_secr",
        "element": v,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Avoid hard-coding passwords, API keys, or cryptographic secrets in variable definitions. Use secure vaults or environment variables instead. (CWE-798)"
    }
}

# Helper functions to identify credential-related names
is_credential_attribute(name) {
    credential_patterns := {"password", "passwd", "pwd", "secret", "key", "token", "api_key", "apikey", "access_key", "secret_key", "private_key", "credentials", "auth"}
    lower := lower(name)
    contains(lower, credential_patterns[_])
}

is_credential_variable(name) {
    credential_patterns := {"password", "passwd", "pwd", "secret", "key", "token", "api_key", "apikey", "access_key", "secret_key", "private_key", "credentials", "auth", "admin_password", "root_password"}
    lower := lower(name)
    contains(lower, credential_patterns[_])
}

looks_like_variable_reference(value) {
    # Check for common variable reference patterns
    regex.match("^\\$\\{.*\\}$", value)
} else {
    regex.match("^\\$[A-Za-z_][A-Za-z0-9_]*$", value)
} else {
    regex.match("^<%.*%>$", value)
} else {
    regex.match("^\\{\\{.*\\}\\}$", value)
}

